import { useState } from 'react';
import {
  Badge,
  Divider,
  Field,
  Heading,
  Section,
  SegmentedControl,
  Select,
  Slider,
  Stack,
  Switch,
  Text,
} from '@jinx-ui/react';

export type Theme = 'light' | 'dark' | 'system';
export type FontFamily = 'system' | 'inter' | 'mono';

export interface AppearanceValue {
  theme: Theme;
  scale: number;
  dense: boolean;
  font: FontFamily;
}

export interface AppearanceSettingsProps {
  initialValue?: Partial<AppearanceValue>;
  onChange: (value: AppearanceValue) => void;
}

const THEMES: { value: Theme; label: string }[] = [
  { value: 'light', label: 'Светлая' },
  { value: 'dark', label: 'Тёмная' },
  { value: 'system', label: 'Системная' },
];

const FONTS: { value: FontFamily; label: string }[] = [
  { value: 'system', label: 'Системный' },
  { value: 'inter', label: 'Inter' },
  { value: 'mono', label: 'Моноширинный' },
];

const DEFAULTS: AppearanceValue = {
  theme: 'system',
  scale: 100,
  dense: false,
  font: 'system',
};

export default function AppearanceSettings({
  initialValue,
  onChange,
}: AppearanceSettingsProps) {
  const [value, setValue] = useState<AppearanceValue>({
    ...DEFAULTS,
    ...initialValue,
  });

  const update = <K extends keyof AppearanceValue>(
    key: K,
    next: AppearanceValue[K],
  ) => {
    setValue((prev) => {
      const merged = { ...prev, [key]: next };
      onChange(merged);
      return merged;
    });
  };

  const themeLabel =
    THEMES.find((t) => t.value === value.theme)?.label ?? value.theme;

  return (
    <Section style={{ padding: 'var(--jx-space-6)' }}>
      <Stack
        direction="row"
        align="center"
        justify="between"
        style={{ marginBottom: 'var(--jx-space-5)' }}
      >
        <Heading level={2}>Внешний вид</Heading>
        <Badge variant="neutral">{themeLabel}</Badge>
      </Stack>

      <Stack direction="column" gap="var(--jx-space-5)">
        <Field label="Тема" htmlFor="appearance-theme">
          <SegmentedControl
            id="appearance-theme"
            value={value.theme}
            onChange={(next: Theme) => update('theme', next)}
            options={THEMES}
          />
        </Field>

        <Field label="Масштаб интерфейса" htmlFor="appearance-scale">
          <Stack direction="row" align="center" gap="var(--jx-space-4)">
            <Slider
              id="appearance-scale"
              min={80}
              max={140}
              step={5}
              value={value.scale}
              onChange={(next: number) => update('scale', next)}
              style={{ flex: 1 }}
            />
            <Text
              variant="body"
              tone="muted"
              style={{ minWidth: 'var(--jx-size-12)', textAlign: 'right' }}
            >
              {value.scale}%
            </Text>
          </Stack>
        </Field>

        <Switch
          checked={value.dense}
          onChange={(next: boolean) => update('dense', next)}
          label="Плотная вёрстка"
          description="Уменьшает отступы между элементами"
        />

        <Divider />

        <Stack direction="column" gap="var(--jx-space-4)">
          <Heading level={3}>Ещё</Heading>
          <Field label="Шрифт" htmlFor="appearance-font">
            <Select
              id="appearance-font"
              value={value.font}
              onChange={(next: FontFamily) => update('font', next)}
              options={FONTS}
            />
          </Field>
        </Stack>
      </Stack>
    </Section>
  );
}

